BEGIN READ ONLY;
SET LOCAL statement_timeout='2000ms';
SELECT jsonb_build_object(
'observed_at',clock_timestamp(),'server_version',current_setting('server_version'),
'max_connections',current_setting('max_connections'),'track_io_timing',current_setting('track_io_timing'),
'connections',(SELECT jsonb_agg(to_jsonb(s)) FROM (SELECT backend_type,state,wait_event_type,wait_event,count(*) n FROM pg_stat_activity WHERE datname=current_database() GROUP BY 1,2,3,4)s),
'active_clients',(SELECT jsonb_agg(to_jsonb(a)) FROM (SELECT pid,application_name,state,wait_event_type,wait_event,query_id,round(extract(epoch FROM clock_timestamp()-query_start)::numeric,3) AS query_age_s,round(extract(epoch FROM clock_timestamp()-xact_start)::numeric,3) AS xact_age_s,pg_blocking_pids(pid) AS blocking_pids,md5(query) AS query_fingerprint FROM pg_stat_activity WHERE datname=current_database() AND backend_type='client backend' AND state IS DISTINCT FROM 'idle' AND pid<>pg_backend_pid() ORDER BY query_start LIMIT 12)a),
'blocked_count',(SELECT count(*) FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid))>0),
'db_stats',(SELECT to_jsonb(d) FROM (SELECT numbackends,deadlocks,temp_files,temp_bytes,stats_reset FROM pg_stat_database WHERE datname=current_database())d),
'slots',(SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT slot_type,active,pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn) AS retained_bytes FROM pg_replication_slots)r)) AS snapshot;
COMMIT;
